#include <iostream>
#include <vector>
#include <queue>
#include <climits>
using namespace std;

struct Edge {
    int u, v;
    long long capacity, flow;
    long long cost;
    long long remaining() { return capacity - flow; }
    Edge() {}
    Edge(int _u, int _v, long long _cap, long long _flow, long long _cost)
        : u(_u), v(_v), capacity(_cap), flow(_flow), cost(_cost) {}
};

vector<int> g[8200];
vector<Edge> e;

void add_edge(int u, int v, long long cap, long long cst) {
    g[u].push_back((int)e.size());
    e.emplace_back(u, v, cap, 0, cst);
    g[v].push_back((int)e.size());
    e.emplace_back(v, u, 0, 0, -cst);
}

long long dist[8200], total_cost;
int parent[8200];
long long bottleneck[8200], total_flow;
bool in_queue[8200];

void min_cost_max_flow(int s, int t) {
    memset(in_queue, 0, sizeof(in_queue));
    total_flow = total_cost = 0;
    while (true) {
        fill(dist, dist + 8200, LLONG_MAX);
        dist[s] = 0;
        memset(parent, -1, sizeof(parent));
        parent[s] = 0;
        memset(bottleneck, 0, sizeof(bottleneck));
        bottleneck[s] = LLONG_MAX;
        queue<int> q;
        q.push(s);
        in_queue[s] = true;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            in_queue[u] = false;
            for (int idx : g[u]) {
                Edge &edge = e[idx];
                if (edge.remaining() > 0 && dist[edge.v] > dist[u] + edge.cost + 1e-9) {
                    dist[edge.v] = dist[u] + edge.cost;
                    parent[edge.v] = idx;
                    bottleneck[edge.v] = min(bottleneck[u], edge.remaining());
                    if (!in_queue[edge.v]) {
                        q.push(edge.v);
                        in_queue[edge.v] = true;
                    }
                }
            }
        }
        if (parent[t] < 0) break;
        long long flow_add = bottleneck[t];
        total_flow += flow_add;
        total_cost += flow_add * dist[t];
        for (int v = t; v != s; v = e[parent[v]].u) {
            e[parent[v]].flow += flow_add;
            e[parent[v] ^ 1].flow -= flow_add;
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m, k, c, d;
    cin >> n >> m >> k >> c >> d;
    for (int i = 0; i < k; i++) {
        int x; cin >> x; x--;
        add_edge(0, x + 1, 1, 0);
    }
    for (int i = 0; i < m; i++) {
        int x, y; cin >> x >> y; x--; y--;
        for (int i = 0; i < 105; i++) {
            for (int j = 0; j < 51; j++) {
                add_edge(i * n + x + 1, (i + 1) * n + y + 1, 1, c + d * (2 * j + 1));
                add_edge(i * n + y + 1, (i + 1) * n + x + 1, 1, c + d * (2 * j + 1));
            }
        }
    }
    for (int i = 0; i < 105; i++) {
        for (int j = 0; j < n; j++) {
            add_edge(i * n + j + 1, (i + 1) * n + j + 1, 51, c);
        }
    }
    for (int i = 0; i < 105; i++) {
        add_edge(i * n + 1, 105 * n + 1, 51, 0);
    }
    int total_nodes = 6 + 107 * n;
    min_cost_max_flow(0, 105 * n + 1);
    cout << total_cost << "\n";
    return 0;
}
